define(['jquery'], function($) {
    'use strict';
    return function(SwatchRenderer) {
        $.widget('mage.SwatchRenderer', $['mage']['SwatchRenderer'], {
            _RenderFormInput: function(config) {
                var msgTxt = $.mage.__("Please select the required *" + config.label + "*");
                return '<input class="' + this.options.classes.attributeInput + ' super-attribute-select" ' + 'name="super_attribute[' + config.id + ']" ' + 'type="text" ' + 'value="" ' + 'data-selector="super_attribute[' + config.id + ']" ' + 'data-validate="{required:true}" ' + 'data-msg-required="' + msgTxt + '" ' + 'aria-required="true" ' + 'aria-invalid="true" ' + 'style="visibility: hidden; position:absolute; left:-1000px">';
            },
            _init: function() {
                if (_.isEmpty(this.options.jsonConfig.images)) {
                    this.options.useAjax = true;
                    this._debouncedLoadProductMedia = _.debounce(this._LoadProductMedia.bind(this), 500);
                }
                if (this.options.jsonConfig !== '' && this.options.jsonSwatchConfig !== '') {
                    this.options.jsonConfig.mappedAttributes = _.clone(this.options.jsonConfig.attributes);
                    this._sortAttributes();
                    this._RenderControls();
                    if (this.options.jsonConfig.attributes.length > 0) {
                        var selectswatch = this.element.find('.' + this.options.classes.attributeClass + ' .' + this.options.classes.attributeOptionsWrapper);
                        $.each(selectswatch, function(index, item) {
                            var swatchOptions = $(item).find('div.swatch-option');
                            var nextEnabled = swatchOptions.not('.disabled').first();
                            if (swatchOptions.length && !swatchOptions.hasClass('selected')) {
                                if (nextEnabled.length) {
                                    nextEnabled.trigger('click');
                                }
                            } else {
                                var select = $(item).find('select');
                                if (select.length > 0) {
                                    var enabledOption = select.find('option:not([disabled])').eq(0);
                                    if (enabledOption.length) {
                                        select.val(enabledOption.val()).trigger('change');
                                    }
                                }
                            }
                        });
                        $.each(selectswatch, function(index, item) {
                            var selected = $(item).find('div.swatch-option.selected');
                            if (selected.length && selected.hasClass('disabled')) {
                                selected.removeClass('selected');
                                var nextEnabled = $(item).find('div.swatch-option:not(.disabled)').first();
                                if (nextEnabled.length) {
                                    nextEnabled.trigger('click');
                                }
                            }
                        });
                    }
                    this._setPreSelectedGallery();
                    $(this.element).trigger('swatch.initialized');
                } else {
                    console.log('SwatchRenderer: No input data received');
                }
                this.options.tierPriceTemplate = $(this.options.tierPriceTemplateSelector).html();
            },
            _OnClick: function($this, $widget) {
                var $parent = $this.parents('.' + $widget.options.classes.attributeClass),
                    $wrapper = $this.parents('.' + $widget.options.classes.attributeOptionsWrapper),
                    $label = $parent.find('.' + $widget.options.classes.attributeSelectedOptionLabelClass),
                    attributeId = $parent.data('attribute-id'),
                    $input = $parent.find('.' + $widget.options.classes.attributeInput),
                    checkAdditionalData = JSON.parse(this.options.jsonSwatchConfig[attributeId]['additional_data']),
                    $priceBox = $widget.element.parents($widget.options.selectorProduct).find(this.options.selectorProductPrice);
                if ($widget.inProductList) {
                    $input = $widget.productForm.find('.' + $widget.options.classes.attributeInput + '[name="super_attribute[' + attributeId + ']"]');
                }
                if ($this.hasClass('disabled')) {
                    return;
                }
                if ($this.hasClass('selected')) {
                    $parent.removeAttr('data-option-selected').find('.selected').removeClass('selected');
                    $input.val('');
                    $label.text('');
                    $this.attr('aria-checked', false);
                } else {
                    $parent.attr('data-option-selected', $this.data('option-id')).find('.selected').removeClass('selected');
                    $label.text($this.data('option-label'));
                    $input.val($this.data('option-id'));
                    $input.attr('data-attr-name', this._getAttributeCodeById(attributeId));
                    $this.addClass('selected');
                    $widget._toggleCheckedAttributes($this, $wrapper);
                }
                $widget._Rebuild();
                if ($priceBox.is(':data(mage-priceBox)')) {
                    $widget._UpdatePrice();
                }
                $(document).trigger('updateMsrpPriceBlock', [this._getSelectedOptionPriceIndex(), $widget.options.jsonConfig.optionPrices, $priceBox]);
                if (parseInt(checkAdditionalData['update_product_preview_image'], 10) === 1) {
                    $widget._loadMedia();
                }
                setTimeout(() => {
                    $(".action.tocompare").attr("child_product_sku", $('.product.attribute.sku .value').text());
                }, 800);
                $input.trigger('change');
            },
        });
        return $['mage']['SwatchRenderer'];
    };
});